package jo.orbitfarm.advisor.alert;
import jo.orbitfarm.advisor.api.ApiException;import jo.orbitfarm.advisor.subscription.SubscriptionService;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.BigDecimal;import java.time.Instant;import java.time.temporal.ChronoUnit;import java.util.List;
@Service public class AlertService{
 private final AlertPreferenceRepository preferences;private final FarmerAlertRepository alerts;private final SubscriptionService subscriptions;
 public AlertService(AlertPreferenceRepository preferences,FarmerAlertRepository alerts,SubscriptionService subscriptions){this.preferences=preferences;this.alerts=alerts;this.subscriptions=subscriptions;}
 @Transactional(readOnly=true)public PreferenceView preference(Long farmerId){AlertPreferenceEntity p=preferences.findByFarmerId(farmerId).orElse(null);return p==null?new PreferenceView(true,false):new PreferenceView(p.isInAppEnabled(),p.isWeatherEnabled());}
 @Transactional public PreferenceView updatePreference(Long farmerId,PreferenceRequest request){AlertPreferenceEntity p=preferences.findByFarmerId(farmerId).orElseGet(()->new AlertPreferenceEntity(farmerId));if(request.weatherEnabled()&&!subscriptions.effectivePlan(farmerId).alerts())throw new ApiException(HttpStatus.FORBIDDEN,"PLAN_FEATURE_REQUIRED","تنبيهات الطقس متاحة ضمن الخطط المدفوعة.");p.update(request.inAppEnabled(),request.weatherEnabled());preferences.save(p);return new PreferenceView(p.isInAppEnabled(),p.isWeatherEnabled());}
 @Transactional(readOnly=true)public List<AlertResponse> list(Long farmerId){if(!subscriptions.effectivePlan(farmerId).alerts())throw new ApiException(HttpStatus.FORBIDDEN,"PLAN_FEATURE_REQUIRED","التنبيهات متاحة ضمن الخطط المدفوعة.");return alerts.findAllByFarmerIdOrderByCreatedAtDesc(farmerId).stream().map(AlertResponse::from).toList();}
 @Transactional public AlertResponse markRead(Long farmerId,Long alertId){FarmerAlertEntity a=alerts.findByIdAndFarmerId(alertId,farmerId).orElseThrow(()->ApiException.notFound("Alert"));a.markRead();return AlertResponse.from(alerts.save(a));}
 @Transactional public void evaluateClimate(Long farmerId,Long farmId,String source,BigDecimal rainfallAnomaly,BigDecimal maxTemp,BigDecimal trend,int rainfallThreshold){if(!subscriptions.effectivePlan(farmerId).alerts())return;AlertPreferenceEntity pref=preferences.findByFarmerId(farmerId).orElse(null);if(pref==null||!pref.isInAppEnabled()||!pref.isWeatherEnabled())return;Instant recent=Instant.now().minus(24,ChronoUnit.HOURS);if(rainfallAnomaly!=null&&rainfallAnomaly.compareTo(BigDecimal.valueOf(-rainfallThreshold))<0&&!alerts.existsByFarmIdAndAlertTypeAndCreatedAtAfter(farmId,"DRY_PERIOD",recent))alerts.save(new FarmerAlertEntity(farmerId,farmId,"DRY_PERIOD","WARNING","مؤشر عجز مطري", "انحراف المطر أقل من الحد المسجل في حزمة التوصية. راجع المصدر والفترة قبل اتخاذ قرار الري.",source));if(maxTemp!=null&&trend!=null&&trend.compareTo(BigDecimal.valueOf(2))>=0&&!alerts.existsByFarmIdAndAlertTypeAndCreatedAtAfter(farmId,"HEAT_TREND",recent))alerts.save(new FarmerAlertEntity(farmerId,farmId,"HEAT_TREND","WARNING","مؤشر ارتفاع حرارة", "تُظهر البيانات اتجاهًا حراريًا مرتفعًا. راجع احتياج المحصول للماء وحدود الحرارة.",source));}
 public record PreferenceRequest(boolean inAppEnabled,boolean weatherEnabled){}public record PreferenceView(boolean inAppEnabled,boolean weatherEnabled){}public record AlertResponse(Long id,Long farmId,String alertType,String severity,String title,String message,String dataSource,Instant createdAt,Instant readAt){static AlertResponse from(FarmerAlertEntity a){return new AlertResponse(a.getId(),a.getFarmId(),a.getAlertType(),a.getSeverity(),a.getTitle(),a.getMessage(),a.getDataSource(),a.getCreatedAt(),a.getReadAt());}}
}
